import React, { useState, useEffect } from 'react';
import api from '../services/api';
import './HomePage.css';

const HomePage = () => {
  const [games, setGames] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAutoPlaying, setIsAutoPlaying] = useState(true);
  const AUTO_PLAY_INTERVAL = 5000;

  useEffect(() => {
    fetchGames();
  }, []);

  useEffect(() => {
    if (!isAutoPlaying || games.length <= 1) return;
    const timer = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % games.length);
    }, AUTO_PLAY_INTERVAL);
    return () => clearInterval(timer);
  }, [isAutoPlaying, games.length]);

  const fetchGames = async () => {
    try {
      const response = await api.get('/games');
      setGames(response.data);
    } catch (err) {
      console.error('Ошибка загрузки игр:', err);
    }
  };

  const nextSlide = () => {
    setCurrentIndex((prev) => (prev + 1) % games.length);
    pauseAutoPlay();
  };

  const prevSlide = () => {
    setCurrentIndex((prev) => (prev - 1 + games.length) % games.length);
    pauseAutoPlay();
  };

  const goToSlide = (index) => {
    setCurrentIndex(index);
    pauseAutoPlay();
  };

  const pauseAutoPlay = () => {
    setIsAutoPlaying(false);
    setTimeout(() => setIsAutoPlaying(true), 8000);
  };

  if (games.length === 0) {
    return (
      <div className="home-page">
        <div className="carousel-loading">Загрузка баннеров...</div>
      </div>
    );
  }

  const currentGame = games[currentIndex];
  // Замените поля на реальные из вашего API
  const imageUrl = currentGame.cover_image || currentGame.image_url || 'https://via.placeholder.com/1200x450/1b2838/66c0f4?text=No+Cover';

  return (
    <div className="home-page">
      <div 
        className="carousel-container" 
        onMouseEnter={() => setIsAutoPlaying(false)}
        onMouseLeave={() => setIsAutoPlaying(true)}
      >
        <div className="carousel-slide active">
          <img src={imageUrl} alt={currentGame.name} className="carousel-image" />
          <div className="carousel-overlay">
            <div className="carousel-content">
              <h2>{currentGame.name}</h2>
              <p className="carousel-desc">{currentGame.description?.slice(0, 150)}...</p>
              <div className="carousel-actions">
                <span className="carousel-price">${currentGame.price ?? '0.00'}</span>
                <button className="carousel-cta-btn">Подробнее</button>
              </div>
            </div>
          </div>
        </div>

        <button className="carousel-btn prev" onClick={prevSlide} aria-label="Предыдущая игра">&#10094;</button>
        <button className="carousel-btn next" onClick={nextSlide} aria-label="Следующая игра">&#10095;</button>

        <div className="carousel-dots">
          {games.map((_, idx) => (
            <button
              key={idx}
              className={`carousel-dot ${idx === currentIndex ? 'active' : ''}`}
              onClick={() => goToSlide(idx)}
              aria-label={`Перейти к игре ${idx + 1}`}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default HomePage;
